import React from 'react';
import { Download, Play } from 'lucide-react';
import { ThemeToggle } from './components/ThemeToggle';
import { ConfigPanel, type SudokuConfig } from './components/ConfigPanel';
import { SudokuGrid } from './components/SudokuGrid';
import { generateSudoku, generatePDF } from './lib/utils';

function App() {
  const [config, setConfig] = React.useState<SudokuConfig>({
    problemsPerPage: 4,
    totalPages: 1,
    solutionsPerPage: 4,
    pageSize: 'A4',
    difficulty: 'medium',
  });

  const [grids, setGrids] = React.useState<{ puzzle: number[][], solution: number[][] }[]>([]);
  const [isGenerated, setIsGenerated] = React.useState(false);
  const [pdfPreview, setPdfPreview] = React.useState<string | null>(null);

  const handleGenerate = () => {
    const totalPuzzles = config.problemsPerPage * config.totalPages;
    const newGrids = Array(totalPuzzles)
      .fill(null)
      .map(() => generateSudoku(config.difficulty));

    setGrids(newGrids);
    setIsGenerated(true);

    // Generate PDF preview
    const pdfDataUrl = generatePDF(newGrids, {
      problemsPerPage: config.problemsPerPage,
      solutionsPerPage: config.solutionsPerPage,
      pageSize: config.pageSize,
    });
    setPdfPreview(pdfDataUrl);
  };

  const handleDownload = () => {
    const link = document.createElement('a');
    link.href = pdfPreview!;
    link.download = 'sudoku-puzzles.pdf';
    link.click();
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100">
      <header className="border-b dark:border-gray-800">
        <div className="container mx-auto px-4 py-4 flex items-center justify-between">
          <h1 className="text-2xl font-bold">Ava Sudoku</h1>
          <ThemeToggle />
        </div>
      </header>

      <main className="container mx-auto px-4 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="space-y-6">
            <ConfigPanel onConfigChange={setConfig} />

            <div className="space-y-4">
              <button
                onClick={handleGenerate}
                className="w-full flex items-center justify-center gap-2 bg-blue-500 hover:bg-blue-600 text-white px-6 py-3 rounded-lg font-medium transition-colors"
              >
                <Play className="h-5 w-5" />
                Generate & Preview
              </button>

              {isGenerated && (
                <button
                  onClick={handleDownload}
                  className="w-full flex items-center justify-center gap-2 bg-green-500 hover:bg-green-600 text-white px-6 py-3 rounded-lg font-medium transition-colors"
                >
                  <Download className="h-5 w-5" />
                  Download PDF
                </button>
              )}
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg p-6 shadow-lg">
            <h2 className="text-xl font-semibold mb-6">Preview</h2>
            <div className="w-full aspect-[1/1.414] bg-white">
              {pdfPreview ? (
                <iframe
                  src={pdfPreview}
                  className="w-full h-full border-0 rounded-lg"
                  title="PDF Preview"
                />
              ) : (
                <div className="flex items-center justify-center h-full text-gray-500 dark:text-gray-400">
                  Click "Generate & Preview" to see the PDF
                </div>
              )}
            </div>
          </div>
        </div>
      </main>

      <footer className="border-t dark:border-gray-800 mt-auto">
        <div className="container mx-auto px-4 py-6 text-center text-gray-600 dark:text-gray-400">
          © {new Date().getFullYear()} <a href='https://github.com/shihabshahrier'>SSA</a>. All rights reserved.
        </div>
      </footer>
    </div>
  );
}

export default App;

import React from 'react';
import { Settings } from 'lucide-react';

interface ConfigPanelProps {
  onConfigChange: (config: SudokuConfig) => void;
}

export interface SudokuConfig {
  problemsPerPage: number;
  totalPages: number;
  solutionsPerPage: number;
  pageSize: 'A4' | 'Letter';
  difficulty: 'easy' | 'medium' | 'hard';
}

export function ConfigPanel({ onConfigChange }: ConfigPanelProps) {
  const [config, setConfig] = React.useState<SudokuConfig>({
    problemsPerPage: 4,
    totalPages: 1,
    solutionsPerPage: 4,
    pageSize: 'A4',
    difficulty: 'medium',
  });

  const handleChange = (key: keyof SudokuConfig, value: string | number) => {
    const newConfig = { ...config, [key]: value };
    setConfig(newConfig);
    onConfigChange(newConfig);
  };

  return (
    <div className="bg-white dark:bg-gray-800 rounded-lg p-6 shadow-lg">
      <div className="flex items-center gap-2 mb-6">
        <Settings className="h-5 w-5 text-blue-500" />
        <h2 className="text-xl font-semibold text-gray-900 dark:text-gray-100">Configuration</h2>
      </div>

      <div className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Problems per page (2-20)
          </label>
          <input
            type="number"
            min="2"
            max="20"
            value={config.problemsPerPage}
            onChange={(e) => handleChange('problemsPerPage', parseInt(e.target.value))}
            className="w-full px-3 py-2 border rounded-md dark:bg-gray-700 dark:border-gray-600"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Total pages
          </label>
          <input
            type="number"
            min="1"
            value={config.totalPages}
            onChange={(e) => handleChange('totalPages', parseInt(e.target.value))}
            className="w-full px-3 py-2 border rounded-md dark:bg-gray-700 dark:border-gray-600"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Solutions per page (2-20)
          </label>
          <input
            type="number"
            min="2"
            max="20"
            value={config.solutionsPerPage}
            onChange={(e) => handleChange('solutionsPerPage', parseInt(e.target.value))}
            className="w-full px-3 py-2 border rounded-md dark:bg-gray-700 dark:border-gray-600"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Page size
          </label>
          <select
            value={config.pageSize}
            onChange={(e) => handleChange('pageSize', e.target.value)}
            className="w-full px-3 py-2 border rounded-md dark:bg-gray-700 dark:border-gray-600"
          >
            <option value="A4">A4</option>
            <option value="Letter">Letter</option>
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Difficulty
          </label>
          <select
            value={config.difficulty}
            onChange={(e) => handleChange('difficulty', e.target.value)}
            className="w-full px-3 py-2 border rounded-md dark:bg-gray-700 dark:border-gray-600"
          >
            <option value="easy">Easy</option>
            <option value="medium">Medium</option>
            <option value="hard">Hard</option>
          </select>
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import { Moon, Sun } from 'lucide-react';

export function ThemeToggle() {
  const [isDark, setIsDark] = React.useState(false);

  React.useEffect(() => {
    const root = window.document.documentElement;
    root.classList.toggle('dark', isDark);
  }, [isDark]);

  return (
    <button
      onClick={() => setIsDark(!isDark)}
      className="rounded-lg p-2.5 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
      aria-label="Toggle theme"
    >
      {isDark ? (
        <Moon className="h-5 w-5 text-gray-600 dark:text-gray-400" />
      ) : (
        <Sun className="h-5 w-5 text-gray-600 dark:text-gray-400" />
      )}
    </button>
  );
}

import { type ClassValue, clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';
import jsPDF from 'jspdf';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

function isValid(board: number[][], row: number, col: number, num: number): boolean {
  // Check row
  for (let x = 0; x < 9; x++) {
    if (board[row][x] === num) return false;
  }

  // Check column
  for (let x = 0; x < 9; x++) {
    if (board[x][col] === num) return false;
  }

  // Check 3x3 box
  const startRow = row - (row % 3), startCol = col - (col % 3);
  for (let i = 0; i < 3; i++) {
    for (let j = 0; j < 3; j++) {
      if (board[i + startRow][j + startCol] === num) return false;
    }
  }

  return true;
}

function solveSudoku(board: number[][]): boolean {
  let row = 0, col = 0, isEmpty = false;

  for (let i = 0; i < 9; i++) {
    for (let j = 0; j < 9; j++) {
      if (board[i][j] === 0) {
        row = i;
        col = j;
        isEmpty = true;
        break;
      }
    }
    if (isEmpty) break;
  }

  if (!isEmpty) return true;

  for (let num = 1; num <= 9; num++) {
    if (isValid(board, row, col, num)) {
      board[row][col] = num;
      if (solveSudoku(board)) return true;
      board[row][col] = 0;
    }
  }

  return false;
}

function getRandomInt(min: number, max: number): number {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

export function generateSudoku(difficulty: 'easy' | 'medium' | 'hard'): { puzzle: number[][], solution: number[][] } {
  const board: number[][] = Array(9).fill(null).map(() => Array(9).fill(0));

  // Fill diagonal 3x3 boxes
  for (let box = 0; box < 9; box += 3) {
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 3; j++) {
        let num;
        do {
          num = getRandomInt(1, 9);
        } while (!isValid(board, box + i, box + j, num));
        board[box + i][box + j] = num;
      }
    }
  }

  // Solve the rest of the board
  solveSudoku(board);

  // Create a copy of the solved board
  const solution = board.map(row => [...row]);

  // Remove numbers based on difficulty
  const cellsToRemove = {
    easy: 30,
    medium: 45,
    hard: 55
  }[difficulty];

  let removed = 0;
  while (removed < cellsToRemove) {
    const row = getRandomInt(0, 8);
    const col = getRandomInt(0, 8);
    if (board[row][col] !== 0) {
      const temp = board[row][col];
      board[row][col] = 0;

      // Check if the puzzle still has a unique solution
      const tempBoard = board.map(row => [...row]);
      let solutionCount = 0;
      const countSolutions = (board: number[][]): boolean => {
        if (solutionCount > 1) return false;

        let row = 0, col = 0, isEmpty = false;
        for (let i = 0; i < 9; i++) {
          for (let j = 0; j < 9; j++) {
            if (board[i][j] === 0) {
              row = i;
              col = j;
              isEmpty = true;
              break;
            }
          }
          if (isEmpty) break;
        }

        if (!isEmpty) {
          solutionCount++;
          return true;
        }

        for (let num = 1; num <= 9; num++) {
          if (isValid(board, row, col, num)) {
            board[row][col] = num;
            if (!countSolutions(board)) return false;
            board[row][col] = 0;
          }
        }

        return true;
      };

      countSolutions(tempBoard);

      if (solutionCount !== 1) {
        board[row][col] = temp;
      } else {
        removed++;
      }
    }
  }

  return { puzzle: board, solution };
}

function calculateOptimalLayout(totalPuzzles: number, pageWidth: number, pageHeight: number, margin: number) {
  const aspectRatio = 1; // Sudoku grids are square
  const minSpacing = 5; // Minimum spacing between grids in mm

  let bestLayout = {
    cols: 1,
    rows: totalPuzzles,
    gridSize: 0,
    spacing: minSpacing
  };

  const availableWidth = pageWidth - (2 * margin);
  const availableHeight = pageHeight - (2 * margin);

  // Try different numbers of columns
  for (let cols = 1; cols <= Math.ceil(Math.sqrt(totalPuzzles)); cols++) {
    const rows = Math.ceil(totalPuzzles / cols);

    // Calculate maximum possible grid size for this layout
    const maxGridWidth = (availableWidth - (minSpacing * (cols - 1))) / cols;
    const maxGridHeight = (availableHeight - (minSpacing * (rows - 1))) / rows;
    const gridSize = Math.min(maxGridWidth, maxGridHeight);

    // Calculate actual spacing to distribute remaining space
    const totalGridWidth = gridSize * cols;
    const totalGridHeight = gridSize * rows;
    const horizontalSpacing = cols > 1 ? (availableWidth - totalGridWidth) / (cols - 1) : minSpacing;
    const verticalSpacing = rows > 1 ? (availableHeight - totalGridHeight) / (rows - 1) : minSpacing;
    const spacing = Math.min(horizontalSpacing, verticalSpacing);

    // Update best layout if this one uses space more efficiently
    if (gridSize > bestLayout.gridSize && spacing >= minSpacing) {
      bestLayout = { cols, rows, gridSize, spacing };
    }
  }

  return bestLayout;
}

export function generatePDF(grids: { puzzle: number[][], solution: number[][] }[], config: {
  problemsPerPage: number,
  solutionsPerPage: number,
  pageSize: 'A4' | 'Letter'
}): string {
  const doc = new jsPDF({
    format: config.pageSize.toLowerCase(),
    unit: 'mm'
  });

  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const margin = 10;

  // Calculate optimal layouts for problems and solutions
  const problemLayout = calculateOptimalLayout(
    config.problemsPerPage,
    pageWidth,
    pageHeight,
    margin
  );

  const solutionLayout = calculateOptimalLayout(
    config.solutionsPerPage,
    pageWidth,
    pageHeight,
    margin
  );

  // Function to draw a single Sudoku grid
  const drawGrid = (grid: number[][], x: number, y: number, size: number) => {
    const cellSize = size / 9;

    // Draw the cells
    doc.setFontSize(Math.max(8, Math.min(12, cellSize * 0.8)));
    doc.setLineWidth(0.1);

    grid.forEach((row, i) => {
      row.forEach((cell, j) => {
        const cellX = x + (j * cellSize);
        const cellY = y + (i * cellSize);

        // Thicker lines for 3x3 boxes
        if (i % 3 === 0) doc.setLineWidth(0.5);
        else doc.setLineWidth(0.1);
        doc.line(cellX, cellY, cellX + cellSize, cellY);

        if (j % 3 === 0) doc.setLineWidth(0.5);
        else doc.setLineWidth(0.1);
        doc.line(cellX, cellY, cellX, cellY + cellSize);

        // Draw number if cell is not empty
        if (cell !== 0) {
          doc.text(
            cell.toString(),
            cellX + (cellSize / 2),
            cellY + (cellSize / 2) + (cellSize * 0.1),
            { align: 'center', baseline: 'middle' }
          );
        }
      });
    });

    // Draw the final borders
    doc.setLineWidth(0.5);
    doc.line(x + size, y, x + size, y + size);
    doc.line(x, y + size, x + size, y + size);
  };

  // Draw problems
  let currentPage = 0;
  grids.forEach((grid, index) => {
    if (index > 0 && index % config.problemsPerPage === 0) {
      doc.addPage();
      currentPage++;
    }

    const pageIndex = index % config.problemsPerPage;
    const col = pageIndex % problemLayout.cols;
    const row = Math.floor(pageIndex / problemLayout.cols);

    const x = margin + col * (problemLayout.gridSize + problemLayout.spacing);
    const y = margin + row * (problemLayout.gridSize + problemLayout.spacing);

    // Add problem number
    doc.setFontSize(8);
    doc.text(`Problem ${index + 1}`, x, y - 2);

    drawGrid(grid.puzzle, x, y, problemLayout.gridSize);
  });

  // Add solutions pages
  if (config.solutionsPerPage > 0) {
    doc.addPage();
    doc.setFontSize(14);
    doc.text('Solutions', margin, margin - 2);

    grids.forEach((grid, index) => {
      if (index > 0 && index % config.solutionsPerPage === 0) {
        doc.addPage();
      }

      const pageIndex = index % config.solutionsPerPage;
      const col = pageIndex % solutionLayout.cols;
      const row = Math.floor(pageIndex / solutionLayout.cols);

      const x = margin + col * (solutionLayout.gridSize + solutionLayout.spacing);
      const y = margin + row * (solutionLayout.gridSize + solutionLayout.spacing);

      // Add solution number
      doc.setFontSize(8);
      doc.text(`Solution ${index + 1}`, x, y - 2);

      drawGrid(grid.solution, x, y, solutionLayout.gridSize);
    });
  }

  return doc.output('datauristring');
}

import React from 'react';
import { cn } from '../lib/utils';

interface SudokuGridProps {
  grid: number[][];
  className?: string;
}

export function SudokuGrid({ grid, className }: SudokuGridProps) {
  return (
    <div className={cn("grid grid-cols-9 gap-0.5 bg-gray-300 p-0.5 rounded-lg", className)}>
      {grid.map((row, i) =>
        row.map((cell, j) => (
          <div
            key={`${i}-${j}`}
            className={cn(
              "aspect-square flex items-center justify-center bg-white dark:bg-gray-800",
              "text-lg font-medium text-gray-900 dark:text-gray-100",
              j % 3 === 2 && "border-r-2 border-gray-300",
              i % 3 === 2 && "border-b-2 border-gray-300"
            )}
          >
            {cell !== 0 && cell}
          </div>
        ))
      )}
    </div>
  );
}
